 "memberships_getMembershipLtvMetrics": {
  "path": "/external/memberships/get-membership-ltv-metrics",
  "summary": "Get Membership LTV Metrics",
  "signature": "{carWashIds: string[], dateRange: {start,end}, ltvFilters: {customerTagIds: string[], employeeIds: string[], packageTemplateIds: string[], promotionIds: string[], upsellIds: string[]}}",
  "scope": "carWashIds",
  "noBody": false,
  "description": "Computes lifetime-value metrics for the cohort of members whose first paid membership billing order landed in the FIRST CALENDAR MONTH of `dateRange.start` — `dateRange.end` only controls how far forward to track that cohort's billing orders, not who is in the cohort. Returns the per-month `stats` array (count of still-billing members and revenue in cents per month from start to end), plus aggregates.\n\n## Aggregates\n\n- `totalLtv`\n- `avgLtv`\n- `avgLifeInMonths`\n- `memberCount` (cohort size at month 0)\n- `totalChurn` and `totalChurnRate` (first-month minus last-month / first-month)\n- `avgMonthlyChurn`\n- `monthlyChurnRate`\n\n## Filters\n\n`ltvFilters` narrow the cohort at signup time — pass empty arrays to include everything:\n\n- `employeeIds`\n- `packageTemplateIds`\n- `promotionIds`\n- `upsellIds`\n- `customerTagIds`\n\nUse this to evaluate the long-tail revenue of a sales month or specific acquisition channel.",
  "schema": {
   "type": "object",
   "properties": {
    "carWashIds": {
     "type": "array",
     "items": {
      "type": "string",
      "description": "a valid car wash ID",
      "pattern": "^(?:(?!^-0$)-?(?:(?:0|[1-9]\\d*)))$",
      "minLength": 1
     }
    },
    "dateRange": {
     "type": "object",
     "properties": {
      "end": {
       "type": "string",
       "description": "date, YYYY-MM-DD"
      },
      "start": {
       "type": "string",
       "description": "date, YYYY-MM-DD"
      }
     },
     "required": [
      "end",
      "start"
     ],
     "additionalProperties": false
    },
    "ltvFilters": {
     "type": "object",
     "properties": {
      "customerTagIds": {
       "type": "array",
       "items": {
        "type": "string",
        "description": "a valid tag ID",
        "pattern": "^(?:[a-f\\d]{8}-[a-f\\d]{4}-[1-8][a-f\\d]{3}-[89ab][a-f\\d]{3}-[a-f\\d]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"
       }
      },
      "employeeIds": {
       "type": "array",
       "items": {
        "type": "string",
        "description": "a valid customer ID",
        "pattern": "^(?:(?!^-0$)-?(?:(?:0|[1-9]\\d*)))$"
       }
      },
      "packageTemplateIds": {
       "type": "array",
       "items": {
        "type": "string",
        "description": "a valid package template ID",
        "pattern": "^(?:[a-f\\d]{8}-[a-f\\d]{4}-[1-8][a-f\\d]{3}-[89ab][a-f\\d]{3}-[a-f\\d]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"
       }
      },
      "promotionIds": {
       "type": "array",
       "items": {
        "type": "string",
        "description": "a valid promotion ID",
        "pattern": "^(?:(?!^-0\\.?0*$)(?:-?(?:(?:0|[1-9]\\d*)(?:\\.\\d+)?)|\\.\\d+?))$"
       }
      },
      "upsellIds": {
       "type": "array",
       "items": {
        "type": "string",
        "description": "a valid upsell UUID",
        "pattern": "^(?:[a-f\\d]{8}-[a-f\\d]{4}-[1-8][a-f\\d]{3}-[89ab][a-f\\d]{3}-[a-f\\d]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"
       }
      }
     },
     "required": [
      "customerTagIds",
      "employeeIds",
      "packageTemplateIds",
      "promotionIds",
      "upsellIds"
     ],
     "additionalProperties": false
    }
   },
   "required": [
    "carWashIds",
    "dateRange",
    "ltvFilters"
   ],
   "additionalProperties": false
  }
 },
